    /// <summary>
    /// Attaches the <c>Main</c> menu and its accelerators to a top-level.
    /// </summary>
    /// <remarks>
    /// The menu is exported natively where the platform has a menu bar (macOS)
    /// and rendered in-window by a <c>NativeMenuBar</c> control everywhere else;
    /// both read the same attached value, so there is no platform branch. Only a
    /// real native menu bar handles its own shortcuts, so the declared gestures
    /// are additionally installed as key bindings on the top-level.
    /// </remarks>
    public static RustMenuAttachment AttachMain(TopLevel target, MainViewModelAdapter model)
    {
        ArgumentNullException.ThrowIfNull(target);
        ArgumentNullException.ThrowIfNull(model);
        var scope = new RustMenuScope(model);
        try
        {
            var keyBindings = new List<KeyBinding>();
            var menu = CreateMain(model, scope, keyBindings);
            return RustMenuAttachment.Attach(target, menu, keyBindings, scope);
        }
        catch
        {
            scope.Dispose();
            throw;
        }
    }

